import {createContext,useContext,useReducer,useState} from "react";import type {Dispatch,ReactNode} from "react";
export type Ticket={id:number;title:string;status:"OPEN"|"CLOSED";assignee:string|null;createdAt:string;tags:string[]};export type State={tickets:readonly Ticket[];selectedId:number|null};export type Action={type:"created";ticket:Ticket}|{type:"closed"|"reopened"|"deleted";id:number}|{type:"selected";id:number|null}|{type:"assigned";id:number;assignee:string|null}|{type:"updated";id:number;changes:Pick<Ticket,"title">}|{type:"bulkClosed";ids:readonly number[]};
export function init(tickets:readonly Ticket[]):State{return {tickets:tickets.map(ticket=>({...ticket,tags:[...ticket.tags]})),selectedId:null};}
export function reducer(state:State,action:Action):State{switch(action.type){case "created":{if(state.tickets.some(ticket=>ticket.id===action.ticket.id))throw Error("Powtórzone ID");const ticket={...action.ticket,tags:[...action.ticket.tags]};return {...state,tickets:[ticket,...state.tickets],selectedId:ticket.id};}case "closed":case "reopened":return {...state,tickets:state.tickets.map(ticket=>ticket.id===action.id?{...ticket,status:action.type==="closed"?"CLOSED":"OPEN"}:ticket)};case "assigned":return {...state,tickets:state.tickets.map(ticket=>ticket.id===action.id?{...ticket,assignee:action.assignee}:ticket)};case "updated":return {...state,tickets:state.tickets.map(ticket=>ticket.id===action.id?{...ticket,title:action.changes.title}:ticket)};case "deleted":return {...state,tickets:state.tickets.filter(ticket=>ticket.id!==action.id),selectedId:state.selectedId===action.id?null:state.selectedId};case "selected":return {...state,selectedId:action.id!==null&&state.tickets.some(ticket=>ticket.id===action.id)?action.id:null};case "bulkClosed":{const ids=new Set(action.ids);return {...state,tickets:state.tickets.map(ticket=>ids.has(ticket.id)?{...ticket,status:"CLOSED"}:ticket)};}default:{const exhaustive:never=action;throw Error("Nieznana akcja: "+JSON.stringify(exhaustive));}}}
export const TicketsContext=createContext<State|null>(null);export const DispatchContext=createContext<Dispatch<Action>|null>(null);
export function TicketsProvider({children,initialTickets}:{children:ReactNode;initialTickets:readonly Ticket[]}){const [state,dispatch]=useReducer(reducer,initialTickets,init);return <TicketsContext value={state}><DispatchContext value={dispatch}>{children}</DispatchContext></TicketsContext>;}
export function useTickets():State{const state=useContext(TicketsContext);if(state===null)throw Error("useTickets wymaga TicketsProvider");return state;}
export function useTicketsDispatch():Dispatch<Action>{const dispatch=useContext(DispatchContext);if(dispatch===null)throw Error("useTicketsDispatch wymaga TicketsProvider");return dispatch;}

